const { getReferredVaults, getReferralPaidTotal } = require("../../../../lib/store");
const { getTotalFees } = require("../../../../lib/keeperDb");
const { REFERRAL_SHARE_OF_FEE } = require("../../../../lib/referral");

const ADDR_RE = /^0x[0-9a-fA-F]{40}$/;

/**
 * GET /api/referrals/:wallet/earnings - public read (a referral's earnings
 * aren't secret, and computing this requires no signature since it only
 * reads, never writes). Sums the platform fee generated by every vault this
 * wallet is credited as referrer for, takes this program's fixed share of
 * it, and subtracts whatever's already been paid out - see
 * scripts/pay-referrals.js for how "paid out" gets recorded.
 *
 * Response: { referredVaultCount, totalEarnedPls, totalPaidPls, pendingPls }
 */
export default function handler(req, res) {
  const { wallet } = req.query;
  if (typeof wallet !== "string" || !ADDR_RE.test(wallet)) {
    res.status(400).json({ error: "wallet must be a 0x-prefixed address" });
    return;
  }
  if (req.method !== "GET") {
    res.setHeader("Allow", ["GET"]);
    res.status(405).json({ error: `method ${req.method} not allowed` });
    return;
  }

  const vaults = getReferredVaults(wallet);
  const totalFeesPls = vaults.reduce((sum, v) => sum + getTotalFees(v), 0);
  const totalEarnedPls = totalFeesPls * REFERRAL_SHARE_OF_FEE;
  const totalPaidPls = getReferralPaidTotal(wallet);
  const pendingPls = Math.max(0, totalEarnedPls - totalPaidPls);

  res.status(200).json({
    referredVaultCount: vaults.length,
    totalEarnedPls,
    totalPaidPls,
    pendingPls,
  });
}
